B.a54=new A.al(B.cH,"Vers\xedculos de agosto","Ya est\xe1n cargados los 9 vers\xedculos de memoria de agosto 2026, de 2 Corintios 5:18 a Colosenses 2:6.")
B.a6S=new A.al(B.dB,'Categor\xeda "R\xe9cords" en el ranking',"Nueva pesta\xf1a en el Ranking que ordena a todos por cu\xe1ntos vers\xedculos tienen en r\xe9cord de velocidad este mes, del que m\xe1s tiene al que menos.")
B.a0a=A.a(s([B.a54,B.a6S]),t.O)
